"""Beat times (voice seconds, read off the whisper words) -> beats.json; captions with per-word times -> caps_<lang>.json."""
import json
KEYS = 'q two second s3 nocomp s4 eq flat s5 chim near s6 farther km2 ent geoid poles s8 stars volc cta vend'.split()
RAW = {'ru': [2.72, 4.16, 6.34, 8.36, 10.22, 12.32, 14.02, 16.32, 17.24, 18.26, 19.76, 21.72, 23.28, 25.06, 26.06, 28.88, 29.86, 31.36, 32.76, 35.28, 36.46, 38.2],
       'kk': [3.22, 4.66, 7.06, 9.78, 12.26, 14.54, 16.98, 18.74, 20.76, 22.48, 24.22, 26.4, 28.4, 29.52, 31.14, 34.28, 35.78, 37.78, 38.76, 41.88, 43.14, 45.2]}
S = {'ru': [(0, 'Эверест — самая высокая точка Земли?'), (2.72, 'Не всё так просто.'), (4.16, 'Есть два способа мерить высоту.'), (6.34, 'И по второму победитель другой.'), (8.36, 'Первый — от уровня моря.'), (10.22, 'Тут Эверест вне конкуренции.'), (12.32, 'Но Земля не идеальный шар.'), (14.02, 'У экватора она толще,'), (15.62, 'как будто немного сплющена.'), (17.24, 'А это вулкан Чимборасо в Эквадоре.'), (19.76, 'Он почти у самого экватора.'), (21.72, 'От центра Земли его вершина дальше, чем Эверест,'), (24.32, 'примерно на два километра.'), (26.06, 'Это бывает на ЕНТ:'), (27.74, 'форма Земли называется геоид,'), (29.66, 'она сжата у полюсов.'), (31.36, 'Получается, ближе всего к звёздам на Земле стоят'), (34.08, 'не на Эвересте, а на этом вулкане.'), (36.46, None)],
     'kk': [(0, 'Эверест — Жердің ең биік нүктесі ме?'), (3.22, 'Бәрі оңай емес.'), (4.66, 'Биіктікті өлшеудің екі жолы бар.'), (7.06, 'Екіншісі бойынша жеңімпаз басқа.'), (9.78, 'Біріншісі — теңіз деңгейінен.'), (12.26, 'Мұнда Эверестке тең келер жоқ.'), (14.54, 'Бірақ Жер мінсіз шар емес.'), (16.98, 'Экватор тұсы жуанырақ,'), (18.74, 'сәл қысылған сияқты.'), (20.76, 'Ал бұл — Эквадордағы Чимборасо жанартауы.'), (24.22, 'Ол экваторға өте жақын.'), (26.4, 'Жердің центрінен оның шыңы Эвересттен шамамен екі шақырым алыс.'), (31.14, 'Бұл ҰБТ-да келеді:'), (33.3, 'Жердің пішіні геоид деп аталады,'), (35.78, 'ол полюстерде қысылған.'), (37.78, 'Сонда Жер бетінде жұлдыздарға ең жақын жер —'), (40.74, 'Эверест емес, осы жанартау.'), (43.14, None)]}
out = {}
for L in ('ru', 'kk'):
    out[L] = {k: v for k, v in zip(KEYS, RAW[L])}
    W = json.load(open(f'words_{L}.json')); caps = []
    for (t0, s), (t1, _) in zip(S[L], S[L][1:]):
        end = max([w[1] for w in W if t0 - .05 <= w[0] < t1 - .05] or [t1 - .3])
        words = s.replace(' —', '').split(' '); tot = sum(len(w) + 2 for w in words); t = t0; tw = []
        for w in words: d = (end - t0) * (len(w) + 2) / tot; tw.append([w, round(t, 2), round(t + d, 2)]); t += d
        cur = []
        for w in tw:
            cur.append(w)
            if len(cur) == 3 or (len(cur) == 2 and len(' '.join(c[0] for c in cur)) > 16) or w[0][-1] in ',.?:':
                caps.append([cur[0][1], cur[-1][2], cur]); cur = []
        if cur: caps.append([cur[0][1], cur[-1][2], cur])
    json.dump(caps, open(f'caps_{L}.json', 'w'), ensure_ascii=False)
    print(L, len(caps), out[L]['vend'])
json.dump(out, open('beats.json', 'w'), indent=0)
